// The generated maintenance `_worker.js` file: how the snapshot is written into it and read back. Kept apart from
// maintenance.js, which loads the converter and Kopje's runtime, so that a command that only reads the snapshot (the
// rollback drain) loads nothing else.

import { ExportError } from "./sql-script.js";

export const WORKER_FILE = "_worker.js";

const PREFIX = "const KOPJE_MAINTENANCE_SNAPSHOT = ";

/**
 * @typedef {{ format: number, domain: string, inboxes: string[],
 *   documents: Record<string, { contentType: string, body: string }> }} Snapshot
 */

/**
 * The generated file: the snapshot, then the runtime bundle, which reads it as KOPJE_MAINTENANCE_SNAPSHOT.
 * @param {unknown} snapshot
 * @param {string} bundle
 */
export function workerSource(snapshot, bundle) {
  const code = bundle.replace(/\n\/\/# sourceMappingURL=\S+\s*$/, "\n");
  return `// Kopje cutover maintenance worker (generated by kopje-admin maintenance-worker; do not edit).\n${PREFIX}${JSON.stringify(snapshot)};\n${code}`;
}

/**
 * The snapshot a generated `_worker.js` carries.
 * @param {string} source
 * @returns {Snapshot}
 */
export function snapshotIn(source) {
  const line = source.split("\n")[1] ?? "";
  if (!line.startsWith(PREFIX) || !line.endsWith(";")) {
    throw new ExportError("not-a-maintenance-worker");
  }
  /** @type {unknown} */
  const snapshot = JSON.parse(line.slice(PREFIX.length, -1));
  return /** @type {Snapshot} */ (snapshot);
}
